def encode(message):
    vowels = 'aeiouAEIOU'
    result = []

    for char in message:
        if char.isalpha():
            # Swap case
            swapped_char = char.swapcase()

            # Check if the original character was a vowel (before swapping)
            if char.lower() in vowels or char.upper() in 'AEIOU':
                # Determine which alphabet to use based on current case of swapped_char
                base_ord = ord('a') if swapped_char.islower() else ord('A')

                # Calculate new character 2 places ahead, wrapping around Z/A
                offset = (ord(swapped_char) - base_ord + 2) % 26
                new_char_code = base_ord + offset

                result.append(chr(new_char_code))
            else:
                result.append(swapped_char)
        else:
            # Non-letter characters are not expected per problem statement, 
            # but we keep them as is just in case.
            result.append(char)

    return ''.join(result)

